__email__ = 'tomasz.krol@nokia.com'

import logging


class CalculateBurst(object):
    min_burst_size = 1
    max_burst_size = 20
    min_burst_period = 2
    max_burst_period = 20000
    min_paging_rate = min_burst_size * 1000 / max_burst_period  # 0.05
    max_paging_rate = max_burst_size * 1000 / min_burst_period  # 10 000

    def __init__(self, paging_rate, burst_size=20):
        self.paging_rate = paging_rate
        self.burst_size = burst_size
        self.burst_period = None
        self.validate_args()

    def validate_args(self):
        self._validate_parameter(param_name='paging rate', value=self.paging_rate,
                                 min_value=self.min_paging_rate, max_value=self.max_paging_rate)
        self._validate_parameter(param_name='burst size', value=self.burst_size,
                                 min_value=self.min_burst_size, max_value=self.max_burst_size)

    @staticmethod
    def _validate_parameter(param_name, value, min_value, max_value):
        if not min_value <= value <= max_value:
            raise ValueError("Passed {} {} is out of range. Burst size should be between [{}, {}]"
                             .format(param_name, value, min_value, max_value))

    def calculate_burst_params(self):
        """
        Method calculate burst_size and burst_period based on passed paging_rate.
        General:
        burst_size - number of messages in burst. Possible values: 1..20
        burst_period - period between burst in ms. Possible values: 2..20000
        paging_rate - max value: 20*1000/2 = 10 000

        paging_rate = burst_size * 1000ms/burst_period
        """

        self.burst_period = int(self.burst_size * 1000 / self.paging_rate)
        try:
            self._validate_parameter(param_name='burst period', value=self.burst_period,
                                     min_value=self.min_burst_period, max_value=self.max_burst_period)
        except ValueError:
            logging.info("Calculated burst period {} is out of range. Burst period should be between {} and {}".
                         format(self.burst_period, self.min_burst_period, self.max_burst_period))
            self.burst_period = self._get_edge_burst_period()
            self.burst_size = int(self.burst_period * self.paging_rate / 10000)

            self._validate_parameter(param_name='burst size', value=self.burst_size,
                                     min_value=self.min_burst_size, max_value=self.max_burst_size)

        self.log_calculated_values()

    def _get_edge_burst_period(self):
        if self.burst_period < self.min_burst_period:
            logging.info("Set burst period to min value")
            return self.min_burst_period
        logging.info("Set burst period to max value")
        return self.max_burst_period

    def log_calculated_values(self):
        calculated_paging_rate = self.burst_size * 1000 / self.burst_period
        logging.info("Automatically calculated paging rate: {}".format(calculated_paging_rate))
        logging.info("Burst size: {}".format(self.burst_size))
        logging.info("Burst period: {}".format(self.burst_period))
